  [(0x7fffc238, [5; 249; 249; 249; 6; 249; 249; 249; 5; 249; 249; 249; 3; 249; 249; 249; 7; 249; 249; 249; 4; 249; 249; 249; 7; 249; 249; 249; 3; 249; 249; 249; 6; 249; 249; 249]);
